import sys, json

# operand classes
FIN, INF, SNAN, QNAN = 0, 1, 2, 3


def solve(req):
    ebits = req['ebits']
    fbits = req['fbits']
    mode = req['mode']
    pairs = req['pairs']

    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits                 # 2**fbits
    Eall = (1 << ebits) - 1
    wshift = ebits + fbits         # position of the sign bit
    vmask = (1 << (wshift + 1)) - 1
    fmask = F - 1
    top = F >> 1                   # top fraction bit (quiet/signal selector)
    emin = 1 - bias
    emax = Eall - 1 - bias
    sub_exp = emin - fbits         # subnormal quantum = 2**sub_exp

    cache = {}

    def dec(h):
        """-> (cls, sign, mant, exp); value = (-1)**sign * mant * 2**exp"""
        r = cache.get(h)
        if r is not None:
            return r
        v = int(h, 16) & vmask
        sign = (v >> wshift) & 1
        e = (v >> fbits) & Eall
        f = v & fmask
        if e == Eall:
            if f == 0:
                r = (INF, sign, 0, 0)
            else:
                r = (QNAN if (f & top) else SNAN, sign, 0, 0)
        elif e == 0:
            r = (FIN, sign, f, sub_exp)          # mant == 0 -> signed zero
        else:
            r = (FIN, sign, F + f, e - bias - fbits)
        cache[h] = r
        return r

    # ---- inspect operands / form products ----
    nan_seen = False
    invalid = False
    inf_neg = False                 # any negative infinite product
    inf_pos = False                 # any positive infinite product
    prods = []                      # (sign, mant, exp) exact finite products

    for pair in pairs:
        a = dec(pair[0])
        b = dec(pair[1])
        for op in (a, b):
            c = op[0]
            if c == QNAN:
                nan_seen = True
            elif c == SNAN:
                nan_seen = True
                invalid = True
        ca = a[0]
        cb = b[0]
        if ca >= SNAN or cb >= SNAN:
            continue               # NaN operand: no product, no 0*inf, no inf
        if ca == INF or cb == INF:
            if (ca == FIN and a[2] == 0) or (cb == FIN and b[2] == 0):
                invalid = True     # zero times infinity
            elif a[1] ^ b[1]:
                inf_neg = True
            else:
                inf_pos = True
            continue
        prods.append((a[1] ^ b[1], a[2] * b[2], a[3] + b[3]))

    def pack(sign, n):
        """encode magnitude n (units of the subnormal quantum) into bit pattern"""
        if n == 0:
            return sign << wshift
        if n < F:
            return (sign << wshift) | n
        dd = n.bit_length() - fbits - 1
        return (sign << wshift) | ((dd + 1) << fbits) | ((n >> dd) - F)

    if nan_seen or invalid:
        bits = (Eall << fbits) | top            # canonical NaN
        return {'bits': format(bits, 'x'),
                'flags': ['invalid'] if invalid else []}

    if inf_pos or inf_neg:
        s = 1 if inf_neg else 0
        return {'bits': format((s << wshift) | (Eall << fbits), 'x'), 'flags': []}

    # ---- exact sum of finite products ----
    nonzero = [p for p in prods if p[1]]
    if nonzero:
        minexp = min(p[2] for p in nonzero)
        total = 0
        for s, m, e in nonzero:
            t = m << (e - minexp)
            total = total - t if s else total + t
    else:
        total = 0

    if total == 0:
        neg = (mode == 'RDN') or (bool(prods) and all(p[0] == 1 for p in prods))
        return {'bits': format(1 << wshift if neg else 0, 'x'), 'flags': []}

    sign = 1 if total < 0 else 0
    num = -total if total < 0 else total      # x = num * 2**minexp, num > 0

    # ---- round the exact magnitude ----
    L = minexp + num.bit_length() - 1        # floor(log2(x))
    k = L - fbits
    if k < sub_exp:
        k = sub_exp                           # quantum q = 2**k
    d = k - minexp
    if d <= 0:
        y = num << (-d)                       # already an exact multiple of q
    else:
        base = num >> d
        rem = num - (base << d)
        half = 1 << (d - 1)
        if mode == 'RTZ':
            y = base
        elif mode == 'RNE':
            if rem > half:
                y = base + 1
            elif rem < half:
                y = base
            else:
                y = base + 1 if (base & 1) else base
        elif mode == 'RNA':
            y = base + 1 if rem >= half else base
        elif mode == 'RUP':
            y = base + 1 if (sign == 0 and rem) else base
        else:                                 # RDN
            y = base + 1 if (sign == 1 and rem) else base

    # ---- overflow: rounded magnitude y*2**k >= 2**(emax+1) ----
    sh = emax + 1 - k
    ovf = y >= (1 << sh) if sh >= 0 else y >= 1
    if ovf:
        away = (mode == 'RNE' or mode == 'RNA' or
                (mode == 'RUP' and sign == 0) or (mode == 'RDN' and sign == 1))
        if away:
            bits = (sign << wshift) | (Eall << fbits)
        else:
            bits = pack(sign, ((F << 1) - 1) << (emax - emin))
        return {'bits': format(bits, 'x'), 'flags': ['overflow', 'inexact']}

    # ---- inexact / underflow ----
    if d <= 0:
        inexact = False
    else:
        inexact = (y << d) != num
    if inexact:
        if k < emin:
            under = y < (1 << (emin - k))
        else:
            under = y == 0
    else:
        under = False

    bits = pack(sign, y << (k - sub_exp))
    flags = []
    if inexact:
        flags.append('inexact')
    if under:
        flags.append('underflow')
    return {'bits': format(bits, 'x'), 'flags': flags}


def main():
    out = sys.stdout
    for line in sys.stdin:
        if not line.strip():
            continue
        try:
            res = solve(json.loads(line))
        except Exception as exc:  # keep line alignment; input should be valid
            print('error: %r' % (exc,), file=sys.stderr)
            res = {'bits': '0', 'flags': []}
        out.write(json.dumps(res))
        out.write('\n')
    out.flush()


if __name__ == '__main__':
    main()
