from fractions import Fraction as Fr


def decode(h, ebits, fbits):
    bias = 2 ** (ebits - 1) - 1
    F = 2 ** fbits
    Eall = 2 ** ebits - 1
    v = int(h, 16) & ((1 << (1 + ebits + fbits)) - 1)
    s = (v >> (ebits + fbits)) & 1
    e = (v >> fbits) & Eall
    f = v & (F - 1)
    if e == Eall:
        if f == 0:
            return ('inf', s, None)
        return ('snan' if not (f >> (fbits - 1)) else 'qnan', s, None)
    if e == 0:
        val = Fr(-1) ** s * f * Fr(2) ** (1 - bias - fbits)
        return ('fin', s, val)
    val = Fr(-1) ** s * (F + f) * Fr(2) ** (e - bias - fbits)
    return ('fin', s, val)


def ref(req):
    ebits, fbits, mode, pairs = req['ebits'], req['fbits'], req['mode'], req['pairs']
    bias = 2 ** (ebits - 1) - 1
    F = 2 ** fbits
    Eall = 2 ** ebits - 1
    emin, emax = 1 - bias, Eall - 1 - bias
    width = 1 + ebits + fbits

    ops = [[decode(h, ebits, fbits) for h in p] for p in pairs]
    nan = any(o[0] in ('qnan', 'snan') for p in ops for o in p)
    invalid = any(o[0] == 'snan' for p in ops for o in p)
    infs = []
    for a, b in ops:
        if a[0] in ('qnan', 'snan') or b[0] in ('qnan', 'snan'):
            continue
        if a[0] == 'inf' or b[0] == 'inf':
            if (a[0] == 'fin' and a[2] == 0) or (b[0] == 'fin' and b[2] == 0):
                invalid = True
            else:
                infs.append((a[1] ^ b[1]))
    if len(set(infs)) > 1:
        invalid = True
    if nan or invalid:
        cn = (Eall << fbits) | (1 << (fbits - 1))
        return format(cn, 'x'), (['invalid'] if invalid else [])

    if infs:
        s = infs[0]
        return format((s << (ebits + fbits)) | (Eall << fbits), 'x'), []

    # exact products with signs
    prods = []
    for a, b in ops:
        v = a[2] * b[2]
        prods.append((a[1] ^ b[1], v))
    total = sum((Fr(-1) ** s) * v for s, v in prods)
    if total == 0:
        neg = (mode == 'RDN') or (len(prods) > 0 and
              all(s == 1 and v == 0 for s, v in prods))
        return format((1 << (ebits + fbits)) if neg else 0, 'x'), []

