    q = Fr(2) ** k
    r = x / q
    y = _round_int(r, mode, sign)
    m = y * q                      # rounded magnitude

    if m >= Fr(2) ** (emax + 1):
        away = mode in ('RNE', 'RNA') or (mode == 'RUP' and sign == 0) or \
               (mode == 'RDN' and sign == 1)
        if away:
            return format((sign << (ebits + fbits)) | (Eall << fbits), 'x'), ['overflow', 'inexact']
        nmax = ((F << 1) - 1) << (emax - emin)
        return _pack(sign, nmax, ebits, fbits), ['overflow', 'inexact']

    flags = []
    if m != x:
        flags.append('inexact')
        if m < Fr(2) ** emin:
            flags.append('underflow')
    u = Fr(2) ** (emin - fbits)
    n = m / u
    assert n.denominator == 1, (n, m, u)
    return _pack(sign, int(n), ebits, fbits), flags


def _floor_log2(x):
    # x is a positive Fraction
    n = x.numerator
    d = x.denominator
    return n.bit_length() - d.bit_length() - (0 if _ge2(Fr(n, d) ** 0) else 0) + _adj(n, d)


def _adj(n, d):
    # returns 0 if n/d >= 2**(bl(n)-bl(d)) else -1  (bl(n)-bl(d) = candidate L)
    cand = n.bit_length() - d.bit_length()
    if (n << (0)) >= (d << cand) if cand >= 0 else (n << (-cand)) >= d:
        return 0
    return -1


