def _round_int(r, mode, sign):
    # round positive Fraction r to a non-negative integer
    n, d = r.numerator, r.denominator
    base, rem = divmod(n, d)
    if rem == 0:
        return base
    if mode == 'RTZ':
        return base
    if mode == 'RNE':
        cmp = 2 * rem - d
        if cmp > 0:
            return base + 1
        if cmp < 0:
            return base
        return base + 1 if base % 2 else base
    if mode == 'RNA':
        return base + 1 if 2 * rem >= d else base
    if mode == 'RUP':
        return base + 1 if sign == 0 else base
    return base + 1 if sign == 1 else base   # RDN


def _pack(sign, n, ebits, fbits):
    F = 2 ** fbits
    Eall = 2 ** ebits - 1
    if n == 0:
        return format(sign << (ebits + fbits), 'x')
    if n < F:
        return format((sign << (ebits + fbits)) | n, 'x')
    e = 1
    while (n >> (e - 1)) >= (F << 1):
        e += 1
    f = (n >> (e - 1)) - F
    assert 0 <= f < F and 1 <= e <= Eall - 1, (n, e, f)
    return format((sign << (ebits + fbits)) | (e << fbits) | f, 'x')
